\begin{ex}%[9D6N1-1]
Hàm số $y=- x^{2}$ thì hệ số của $x^{2}$ là 
\choice
{ $-7$  }
   { \True $-1$  }
     { $0$ }
    { $-2$  }
\loigiai{
